<?php
require 'config.php';require_login();$pageTitle='Students';$active='students';$action=$_GET['action']??'list';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
$id=(int)($_POST['id']??0);$reg=trim($_POST['register_number']??'');$name=trim($_POST['name']??'');$dept=trim($_POST['department']??'');$year=(int)($_POST['year']??0);$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');
if(!$reg||!$name||!$dept||$year<1||$year>3)$error='Complete required fields. Academic year must be 1, 2 or 3.';
else{try{if($id){$s=$conn->prepare('UPDATE students SET register_number=?,name=?,department=?,year=?,email=?,phone=?,address=? WHERE id=?');$s->bind_param('sssisssi',$reg,$name,$dept,$year,$email,$phone,$address,$id);}else{$s=$conn->prepare('INSERT INTO students(register_number,name,department,year,email,phone,address) VALUES(?,?,?,?,?,?,?)');$s->bind_param('sssisss',$reg,$name,$dept,$year,$email,$phone,$address);}$s->execute();flash('success',$id?'Student updated successfully.':'Student added successfully.');header('Location: students.php');exit;}catch(Throwable $e){$error='Register number may already exist, or the record could not be saved.';}}
$action=$id?'edit':'add';}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$s=$conn->prepare('DELETE FROM students WHERE id=?');$s->bind_param('i',$id);$s->execute();flash('success','Student and related attendance/marks records deleted.');header('Location: students.php');exit;}
$edit=null;if($action==='edit'){$id=(int)($_GET['id']??0);$s=$conn->prepare('SELECT * FROM students WHERE id=?');$s->bind_param('i',$id);$s->execute();$edit=$s->get_result()->fetch_assoc();if(!$edit){header('Location: students.php');exit;}}
$q=trim($_GET['q']??'');if($q!==''){$like='%'.$q.'%';$s=$conn->prepare('SELECT * FROM students WHERE name LIKE ? OR register_number LIKE ? OR department LIKE ? ORDER BY id DESC');$s->bind_param('sss',$like,$like,$like);$s->execute();$list=$s->get_result();}else{$list=$conn->query('SELECT * FROM students ORDER BY id DESC');}
require 'includes/header.php';?>
<div class="heading"><div><p class="eyebrow">STUDENT DIRECTORY</p><h1>Student records</h1><p class="muted">Manage profiles, departments and enrolment information.</p></div><a class="btn primary" href="students.php?action=add">＋ Add student</a></div>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<?php if(in_array($action,['add','edit'])): ?><section class="card formcard"><div class="cardhead"><div><h2><?=$action==='edit'?'Edit student profile':'Add a new student'?></h2><p class="muted">Fields marked * are required.</p></div><a class="textlink" href="students.php">← Back to directory</a></div><form method="post" class="formgrid"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"/>
<label>Register number *<input required name="register_number" value="<?=e($edit['register_number']??'')?>" placeholder="e.g. 2610201"></label><label>Full name *<input required name="name" value="<?=e($edit['name']??'')?>" placeholder="Student full name"></label>
<label>Department *<select name="department" required><option value="">Select department</option><?php foreach(['Computer Engineering','Mechanical Engineering','Electrical and Electronics Engineering','Electronics and Communication Engineering','Civil Engineering','Information Technology'] as $d):?><option <?=($edit['department']??'')===$d?'selected':''?>><?=e($d)?></option><?php endforeach;?></select></label>
<label>Academic year *<select name="year" required><option value="">Select year</option><?php for($i=1;$i<=3;$i++):?><option value="<?=$i?>" <?=((int)($edit['year']??0)===$i)?'selected':''?>>Year <?=$i?></option><?php endfor;?></select></label>
<label>Email address<input type="email" name="email" value="<?=e($edit['email']??'')?>" placeholder="student@example.com"></label><label>Phone number<input name="phone" value="<?=e($edit['phone']??'')?>" placeholder="Contact number"></label><label class="wide">Address<textarea name="address" rows="3" placeholder="Student address"><?=e($edit['address']??'')?></textarea></label><div class="actions"><a class="btn secondary" href="students.php">Cancel</a><button class="btn primary"><?= $action==='edit'?'Save changes':'Save student'?> →</button></div></form></section>
<?php else: ?><section class="card"><div class="cardhead"><div><h2>All students <span class="count"><?=$list->num_rows?></span></h2><p class="muted">Search and manage all registered students.</p></div><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search name, register no..."><button>Search</button><?php if($q):?><a href="students.php">Clear</a><?php endif;?></form></div><div class="tablewrap"><table><thead><tr><th>STUDENT</th><th>DEPARTMENT</th><th>YEAR</th><th>CONTACT</th><th>ADDED</th><th>ACTIONS</th></tr></thead><tbody>
<?php if($list->num_rows):while($s=$list->fetch_assoc()):?><tr><td><b><?=e($s['name'])?></b><small><?=e($s['register_number'])?></small></td><td><?=e($s['department'])?></td><td>Year <?= (int)$s['year']?></td><td><?=e($s['email']?:'—')?><small><?=e($s['phone']?:'')?></small></td><td><?=date('d M Y',strtotime($s['created_at']))?></td><td><a class="iconlink" href="students.php?action=edit&id=<?=$s['id']?>">✎</a> <a class="iconlink danger" onclick="return confirm('Delete this student and related records?')" href="students.php?delete=<?=$s['id']?>">⌫</a></td></tr><?php endwhile;else:?><tr><td colspan="6" class="empty">No students found. Add a student or try another search.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?>
<?php require 'includes/footer.php'; ?>